            var before=await client.GetFromJsonAsync<JsonObject>($"/api/v1/vaults/{vault}/encryption/payloads/knowledge/{item}");var exactBefore=before!["record"]!.ToJsonString();var originalRefs=before["payloadKeyReferences"]!.ToJsonString();var originalFields=before["record"]!["encryptedFieldsJson"]!.GetValue<string>();Assert.Equal("knowledge:title",DecryptOriginalAiField(originalFields,protectedContent));
