            using var response=await AiRunAsync(client,item,vault,challenge.GetProperty("challengeId").GetGuid(),revision);if(mode.StartsWith("late-")){Assert.Contains(response.StatusCode,new[]{HttpStatusCode.Forbidden,HttpStatusCode.Conflict});Assert.DoesNotContain("PRIVATE_GENERATED_RESULT",await response.Content.ReadAsStringAsync());Assert.Equal(1,model.Calls);return;}Assert.Equal(HttpStatusCode.OK,response.StatusCode);var draft=await response.Content.ReadFromJsonAsync<JsonElement>();Assert.False(draft.GetProperty("saved").GetBoolean());var afterDraft=await client.GetFromJsonAsync<JsonObject>($"/api/v1/vaults/{vault}/encryption/payloads/knowledge/{item}");Assert.Equal(exactBefore,afterDraft!["record"]!.ToJsonString());Assert.Equal(originalRefs,afterDraft["payloadKeyReferences"]!.ToJsonString());
