            if(protectedContent){var fields=JsonNode.Parse(EncryptCurrentTitle(body,selected.PublicKey))!;fields["fields"]!["content"]=fields["fields"]!["title"]!.DeepClone();fields["fields"]!.AsObject().Remove("title");record["encryptedFieldsJson"]=fields.ToJsonString();var reference=refs.Single(r=>r!["fieldName"]!.GetValue<string>()=="content")!;reference["fingerprint"]=selected.Fingerprint;reference["generation"]=2;}
            else if(!encrypted)record["content"]=body;else{var reference=refs.Single(r=>r!["role"]!.GetValue<string>()=="body")!;var binding=reference["originalBindingId"]!.GetValue<Guid>();var envelope=ShCustodyCanaryCrypto.Encrypt(selected.PublicKey,Encoding.UTF8.GetBytes(body),binding);record["ciphertext"]=envelope.Ciphertext;record["encryptedDek"]=envelope.WrappedDek;record["encryptedDekNonce"]=envelope.DekNonce;record["dekNonce"]=envelope.DekNonce;record["ephemeralPublicKey"]=envelope.EphemeralPublicKey;record["contentNonce"]=envelope.ContentNonce;record["envelopeVersion"]=2;record["encryptionKeyRef"]=null;reference["fingerprint"]=selected.Fingerprint;reference["generation"]=2;}
