    private static string DecryptOriginalAiField(string fields,bool protectedContent)
    {
        if(!protectedContent)return DecryptCurrentField(fields);
        var sidecar=JsonNode.Parse(fields)!;sidecar["fields"]!["title"]=sidecar["fields"]!["content"]!.DeepClone();return DecryptCurrentField(sidecar.ToJsonString());
    }
    private static string DecryptAiContentField(string fields,Key key)
    {
        var field=JsonNode.Parse(fields)!["fields"]!["content"]!;
        return DecryptLocalAiBody(new(){Ciphertext=field["ciphertext"]!.GetValue<string>(),EncryptedDek=field["encryptedDek"]!.GetValue<string>(),EncryptedDekNonce=field["dekNonce"]!.GetValue<string>(),ContentNonce=field["contentNonce"]!.GetValue<string>(),EphemeralPublicKey=field["ephemeralPublicKey"]!.GetValue<string>(),EnvelopeVersion=1},key);
    }
    private static string DecryptLocalAiBody(SealedKnowledgeItem item,Key key)
    {
        var ephemeral=Convert.FromBase64String(item.EphemeralPublicKey!);using var shared=KeyAgreementAlgorithm.X25519.Agree(key,PublicKey.Import(KeyAgreementAlgorithm.X25519,ephemeral,KeyBlobFormat.RawPublicKey))!;
        var wrapping=KeyDerivationAlgorithm.HkdfSha256.DeriveBytes(shared,ephemeral,"knowz-dek-wrap-v1"u8.ToArray(),32);var dek=new byte[32];var cipher=Convert.FromBase64String(item.Ciphertext);var clear=new byte[cipher.Length-16];
        try{var wrapped=Convert.FromBase64String(item.EncryptedDek!);using(var aes=new AesGcm(wrapping,16))aes.Decrypt(Convert.FromBase64String(item.EncryptedDekNonce!),wrapped.AsSpan(0,32),wrapped.AsSpan(32),dek);using(var aes=new AesGcm(dek,16))aes.Decrypt(Convert.FromBase64String(item.ContentNonce!),cipher.AsSpan(0,clear.Length),cipher.AsSpan(clear.Length),clear,item.EnvelopeVersion==2?Encoding.UTF8.GetBytes($"knowz-msg-v2|{item.CryptoBindingId:D}|x25519-vault-public|2"):[]);return Encoding.UTF8.GetString(clear);}
        finally{CryptographicOperations.ZeroMemory(wrapping);CryptographicOperations.ZeroMemory(dek);CryptographicOperations.ZeroMemory(clear);}
    }
